class Solution {
public:
    int countBalancedPermutations(string num) {
        const long long MOD = 1000000007;
        vector<int> count(10, 0);
        int total_sum = 0;
        for (char ch : num) {
            int d = ch - '0';
            count[d]++;
            total_sum += d;
        }

        if (total_sum % 2 != 0) return 0;

        int n = num.size();
        int odd_slots = n / 2;
        int target = total_sum / 2;

        vector<long long> fact(n + 1, 1), inv(n + 1, 1);
        for (int i = 1; i <= n; ++i) fact[i] = (fact[i - 1] * i) % MOD;

        auto power = [&](long long base, long long exp) {
            long long res = 1;
            while (exp > 0) {
                if (exp & 1) res = (res * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return res;
        };

        inv[n] = power(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; --i) inv[i] = (inv[i + 1] * (i + 1)) % MOD;

        auto comb = [&](int n, int r) -> long long {
            if (r < 0 || r > n) return 0;
            return fact[n] * inv[r] % MOD * inv[n - r] % MOD;
        };

        vector<int> pref(11, 0);
        for (int d = 0; d < 10; ++d) pref[d + 1] = pref[d] + count[d];

        vector<vector<vector<long long>>> memo(11, vector<vector<long long>>(odd_slots + 1, vector<long long>(target + 1, -1)));

        auto dp = [&](auto& self, int d, int o_slots, int o_sum) -> long long {
            if (d == 10) return (o_slots == 0 && o_sum == 0) ? 1 : 0;
            if (o_sum < 0 || o_slots < 0) return 0;
            int digits_left = n - pref[d];
            int e_slots = digits_left - o_slots;
            if (e_slots < 0) return 0;

            if (memo[d][o_slots][o_sum] != -1) return memo[d][o_slots][o_sum];

            long long res = 0;
            int cnt = count[d];
            for (int k = 0; k <= min(cnt, o_slots); ++k) {
                int even_take = cnt - k;
                if (even_take <= e_slots && o_sum >= k * d) {
                    long long ways = comb(o_slots, k) * comb(e_slots, even_take) % MOD;
                    long long sub = self(self, d + 1, o_slots - k, o_sum - k * d);
                    res = (res + ways * sub) % MOD;
                }
            }
            return memo[d][o_slots][o_sum] = res;
        };

        return dp(dp, 0, odd_slots, target);
    }
};

class Solution {
    public int countBalancedPermutations(String num) {
        long MOD = 1_000_000_007;
        int[] count = new int[10];
        int totalSum = 0;
        for (int i = 0; i < num.length(); i++) {
            int d = num.charAt(i) - '0';
            count[d]++;
            totalSum += d;
        }

        if (totalSum % 2 != 0) return 0;

        int n = num.length();
        int oddSlots = n / 2;
        int target = totalSum / 2;

        long[] fact = new long[n + 1];
        long[] inv = new long[n + 1];
        fact[0] = inv[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = (fact[i - 1] * i) % MOD;
        inv[n] = power(fact[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; i--) inv[i] = (inv[i + 1] * (i + 1)) % MOD;

        int[] pref = new int[11];
        for (int d = 0; d < 10; d++) pref[d + 1] = pref[d] + count[d];

        Long[][][] memo = new Long[11][oddSlots + 1][target + 1];
        return (int) solve(0, oddSlots, target, count, pref, n, fact, inv, MOD, memo);
    }

    private long solve(int d, int oSlots, int oSum, int[] count, int[] pref, int n, long[] fact, long[] inv, long MOD, Long[][][] memo) {
        if (d == 10) return (oSlots == 0 && oSum == 0) ? 1 : 0;
        if (oSum < 0 || oSlots < 0) return 0;
        int digitsLeft = n - pref[d];
        int eSlots = digitsLeft - oSlots;
        if (eSlots < 0) return 0;

        if (memo[d][oSlots][oSum] != null) return memo[d][oSlots][oSum];

        long res = 0;
        int cnt = count[d];
        for (int k = 0; k <= Math.min(cnt, oSlots); k++) {
            int evenTake = cnt - k;
            if (evenTake <= eSlots && oSum >= k * d) {
                long ways = comb(oSlots, k, fact, inv, MOD) * comb(eSlots, evenTake, fact, inv, MOD) % MOD;
                long sub = solve(d + 1, oSlots - k, oSum - k * d, count, pref, n, fact, inv, MOD, memo);
                res = (res + ways * sub) % MOD;
            }
        }
        return memo[d][oSlots][oSum] = res;
    }

    private long comb(int n, int r, long[] fact, long[] inv, long MOD) {
        if (r < 0 || r > n) return 0;
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD;
    }

    private long power(long base, long exp, long MOD) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }
}

var countBalancedPermutations = function(num) {
    const MOD = 1000000007n;
    const count = new Array(10).fill(0);
    let totalSum = 0;
    for (let i = 0; i < num.length; i++) {
        const d = Number(num[i]);
        count[d]++;
        totalSum += d;
    }

    if (totalSum % 2 !== 0) return 0;

    const n = num.length;
    const oddSlots = Math.floor(n / 2);
    const target = Math.floor(totalSum / 2);

    const fact = new Array(n + 1).fill(1n);
    const inv = new Array(n + 1).fill(1n);
    for (let i = 1; i <= n; i++) fact[i] = (fact[i - 1] * BigInt(i)) % MOD;

    function power(base, exp) {
        let res = 1n;
        base = BigInt(base);
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp & 1n) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1n;
        }
        return res;
    }

    inv[n] = power(fact[n], MOD - 2n);
    for (let i = n - 1; i >= 0; i--) inv[i] = (inv[i + 1] * BigInt(i + 1)) % MOD;

    function comb(n, r) {
        if (r < 0 || r > n) return 0n;
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD;
    }

    const pref = new Array(11).fill(0);
    for (let d = 0; d < 10; d++) pref[d + 1] = pref[d] + count[d];

    const memo = new Map();

    function solve(d, oSlots, oSum) {
        if (d === 10) return (oSlots === 0 && oSum === 0) ? 1n : 0n;
        if (oSum < 0 || oSlots < 0) return 0n;
        const digitsLeft = n - pref[d];
        const eSlots = digitsLeft - oSlots;
        if (eSlots < 0) return 0n;

        const key = `${d},${oSlots},${oSum}`;
        if (memo.has(key)) return memo.get(key);

        let res = 0n;
        const cnt = count[d];
        for (let k = 0; k <= Math.min(cnt, oSlots); k++) {
            const evenTake = cnt - k;
            if (evenTake <= eSlots && oSum >= k * d) {
                const ways = comb(oSlots, k) * comb(eSlots, evenTake) % MOD;
                const sub = solve(d + 1, oSlots - k, oSum - k * d);
                res = (res + ways * sub) % MOD;
            }
        }
        memo.set(key, res);
        return res;
    }

    return Number(solve(0, oddSlots, target));
};
